import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        sets = []
        for _ in range(m):
            v_i = int(next(iterator))
            s = set()
            for _ in range(v_i):
                s.add(int(next(iterator)))
            sets.append(s)

        signatures = {}

        for x in range(n):
            sig = 0
            for idx, s in enumerate(sets):
                if x in s:
                    sig |= (1 << idx)

            if sig not in signatures:
                signatures[sig] = []
            signatures[sig].append(x)

        count = 0
        for sig in signatures:
            if sig != 0:
                count += 1

        results.append(str(count))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
